function authSession(){try{return JSON.parse(sessionStorage.getItem("mechpro-session"))}catch{return null}}
function clearAuthSession(){sessionStorage.removeItem("mechpro-session")}
async function apiFetch(path,options={}){const session=authSession();if(!session)throw new Error("Not signed in");const response=await fetch(`${cognitoConfig.apiUrl}${path}`,{...options,headers:{"Content-Type":"application/json",Authorization:`Bearer ${session.idToken}`,...(options.headers||{})}});if(!response.ok)throw new Error(`API request failed: ${response.status}`);return response.status===204?null:response.json()}
